# Recreate sheet 'PRUEBAS DE ALTO NIVEL' to ensure clean layout without conflicting merged cells
if 'PRUEBAS DE ALTO NIVEL' in wb.sheetnames:
    del wb['PRUEBAS DE ALTO NIVEL']
ws_an = wb.create_sheet(title='PRUEBAS DE ALTO NIVEL', index=3)

headers_an = ['HISTORIA DE USUARIO', 'CASO DE PRUEBA', 'DESCRIPCION', 'PRECONDICION', 'CRITERIO DE ACEPTACION', 'RESULTADO ESPERADO', 'RESULTADO OBTENIDO']
for col_idx, h in enumerate(headers_an, 1):
    cell = ws_an.cell(1, col_idx)
    cell.value = h
    cell.fill = PatternFill(start_color="FFBDD6EE", end_color="FFBDD6EE", fill_type="solid")
    cell.font = Font(name="Calibri", size=11, bold=True)
    cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)

for i, tc in enumerate(test_cases, 2):
    ws_an.cell(i, 1).value = f"[{tc['rol']}] {tc['pbi']}"
    ws_an.cell(i, 2).value = tc['cp']
    ws_an.cell(i, 3).value = tc['cp_alto_nivel']
    ws_an.cell(i, 4).value = tc['prerequisito']
    ws_an.cell(i, 5).value = tc['criterio_de_aceptacion']
    ws_an.cell(i, 6).value = tc['resultado_esperado']
    ws_an.cell(i, 7).value = tc['resultado_obtenido']
    
    for c in range(1, 8):
        cell = ws_an.cell(i, c)
        cell.font = Font(name="Calibri", size=10)
        cell.alignment = Alignment(horizontal="left", vertical="top", wrap_text=True)
        cell.border = Border(
            left=Side(style='thin', color='D9D9D9'),
            right=Side(style='thin', color='D9D9D9'),
            top=Side(style='thin', color='D9D9D9'),
            bottom=Side(style='thin', color='D9D9D9')
        )

# Create 5 detailed sheets by role
roles_list = [
    ("AdminTI", "Administrador TI"),
    ("Recepcionista", "Recepcionista / Secretaria"),
    ("Odontologo", "Odontólogo"),
    ("AsistenteDental", "Asistente Dental"),
    ("Gerencia", "Gerente / Gerencia")
]

detailed_headers = [
    'CASO DE PRUEBA', 'TIPO ', 'TIPO DE PRUEBA', 'REQUERIMIENTO', 'REGLA DE NEGOCIO', 
    'ALCANCE', 'CASO DE PRUEBA DE ALTO NIVEL', 'DESCRIPCION DETALLADA DE LA PRUEBA', 
    'PREREQUISITO', 'CRITERIO DE ACEPTACION', 'RESULTADO ESPERADO', 'RESULTADO OBTENIDO', 'OBSERVACION'
]

for sheet_code, role_name in roles_list:
    sheet_title = f"Detalle_{sheet_code}"
    if sheet_title in wb.sheetnames:
        del wb[sheet_title]
    ws_role = wb.create_sheet(title=sheet_title)
    
    # Headers
    for col_idx, h in enumerate(detailed_headers, 1):
        cell = ws_role.cell(1, col_idx)
        cell.value = h
        cell.fill = PatternFill(start_color="FFBDD6EE", end_color="FFBDD6EE", fill_type="solid")
        cell.font = Font(name="Calibri", size=11, bold=True)
        cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
        
    role_tcs = [tc for tc in test_cases if tc['rol'] == role_name]
    for row_idx, tc in enumerate(role_tcs, 2):
        ws_role.cell(row_idx, 1).value = tc['cp']
        ws_role.cell(row_idx, 2).value = tc['tipo']
        ws_role.cell(row_idx, 3).value = tc['tipo_de_prueba']
        ws_role.cell(row_idx, 4).value = tc['requerimiento']
        ws_role.cell(row_idx, 5).value = tc['regla_de_negocio']
        ws_role.cell(row_idx, 6).value = tc['alcance']
        ws_role.cell(row_idx, 7).value = tc['cp_alto_nivel']
        ws_role.cell(row_idx, 8).value = tc['descripcion_detallada']
        ws_role.cell(row_idx, 9).value = tc['prerequisito']
        ws_role.cell(row_idx, 10).value = tc['criterio_de_aceptacion']
        ws_role.cell(row_idx, 11).value = tc['resultado_esperado']
        ws_role.cell(row_idx, 12).value = tc['resultado_obtenido']
        ws_role.cell(row_idx, 13).value = tc['observacion']
        
        for c in range(1, 14):
            cell = ws_role.cell(row_idx, c)
            cell.font = Font(name="Calibri", size=10)
            cell.alignment = Alignment(horizontal="left", vertical="top", wrap_text=True)
            cell.border = Border(
                left=Side(style='thin', color='D9D9D9'),
                right=Side(style='thin', color='D9D9D9'),
                top=Side(style='thin', color='D9D9D9'),
                bottom=Side(style='thin', color='D9D9D9')
            )

# Auto-adjust column widths for readability
for ws in wb.worksheets:
    for col in ws.columns:
        max_len = 0
        col_letter = get_column_letter(col[0].column)
        for cell in col[:15]:
            val_str = str(cell.value or '')
            first_line = val_str.split('\n')[0]
            max_len = max(max_len, min(len(first_line), 45))
        ws.column_dimensions[col_letter].width = max(max_len + 4, 12)

wb.save('Grupo#_CARNETSINTEGRANTES_PlandePruebas.xlsx')
